    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (!optlen)
        return -EINVAL;

    if (!sock->sk->sk_bound_dev_if)
        return -EADDRNOTAVAIL;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    if (session->session_id == 0) {
        /* Tunnel options */
        err = pppol2tp_set_tunnel_options(session->tunnel, optname, optval, optlen);
    } else {
        /* Session options */
        err = pppol2tp_set_session_options(session, optname, optval, optlen);
    }

    pppol2tp_put_session(session);
    return err;
}

