int setsockopt_pppol2tp(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    int ret = 0;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(u32))
        return -EINVAL;

    u32 value;
    if (copy_from_user(&value, optval, sizeof(u32)))
        return -EFAULT;

    if (!sock->sk->sk_state || sock->sk->sk_state != PPPOX_CONNECTED)
        return -ENOTCONN;

    session = pppol2tp_get_session(sock);
    if (!session)
        return -ENOENT;

    switch (optname) {
        case PPPOPT_TUNNEL_ID:
            session->tunnel_id = value;
            break;
        case PPPOPT_SESSION_ID:
            session->session_id = value;
            break;
        default:
            ret = -EINVAL;
    }

    return ret;
}

int pppol2tp_setsockopt(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    int err = -EFAULT;
    struct sock *sk = sock->sk;
    struct pppol2tp_sock *po = pppol2tp_sk(sk);
    struct pppol2tp_session *session = po->session;

    if (level != SOL_PPPOL2TP)
        return -ENOPROTOOPT;

    if (optlen < sizeof(int))
        return -EINVAL;

    {
        int val;
        if (copy_from_user(&val, optval, sizeof(val)))
            goto out;
        switch (optname) {
        case PPCP_SETSESSION:
            if (session && session->session_id != val) {
                session = pppol2tp_find_session(val);
                if (!session)
                    return -ENOENT;
                po->session = session;
            }
            break;
        case PPCP_SETTUNNEL:
            if (session->tunnel->tunnel_id != val) {
                struct pppol2tp_tunnel *tunnel = pppol2tp_find_tunnel(val);
                if (!tunnel)
                    return -ENOENT;
                session->tunnel = tunnel;
            }
            break;
        default:
            return -ENOPROTOOPT;
        }
        err = 0;
    }

out:
    return err;
}
